def max_contribution(du):
    # N=11 vertices, max degree 10.
    # Contribution C_u = sum(|du - dv|) for neighbors v.
    # Maximize by setting dv to 0 or 10.
    if du <= 5:
        return du * (10 - du)
    else:
        return du * du

print(f"d_u=1: {max_contribution(1)}")
print(f"d_u=5: {max_contribution(5)}")
print(f"d_u=6: {max_contribution(6)}")
print(f"d_u=10: {max_contribution(10)}")

def S(k):
    return 2 * k * (9 - k)

k_values = range(1, 6)
results = {k: S(k) for k in k_values}
print(results)
